#include "tag-file-transaction.hpp"
#include "tag-certification.hpp"

static void commit(const json& r){
 if(!keys(r,{"version","kind","operationId","jobId","leaseId","leaseRevision","certificateId","sourceRoot","backupRoot","files","expected","victimArtifactId"})||r.at("version")!=1||r.at("kind")!="commit"||!uuid(r.at("jobId").get<std::string>())||!uuid(r.at("leaseId").get<std::string>())||!uuid(r.at("victimArtifactId").get<std::string>())||!r.at("leaseRevision").is_number_unsigned()||r.at("leaseRevision").get<uint64_t>()<1||r.at("leaseRevision").get<uint64_t>()>9007199254740991ULL||!tag_certification::permits(r.at("certificateId").get<std::string>()))throw std::runtime_error("uncertified commit or invalid frozen identity");
 auto expected=r.at("expected"),paths=r.at("files");if(!keys(expected,{"files","roots","exclusiveRead"})||expected.at("exclusiveRead")!=true||!expected.at("files").is_array()||expected.at("files").size()!=3||!expected.at("roots").is_array()||expected.at("roots").size()!=2||!paths.is_array()||paths.size()!=3)throw std::runtime_error("commit baseline shape");
 const auto sourceRoot=normal(wide(r.at("sourceRoot").get<std::string>())),backupRoot=normal(wide(r.at("backupRoot").get<std::string>()));DirectoryPins pins;HANDLE source=pins.pin(sourceRoot),backup=pins.pin(backupRoot);json roots={identity(source,true),identity(backup,true)};
 for(size_t i=0;i<2;i++)for(const char* key:{"volume","fileId","creation"})if(roots.at(i).at(key)!=expected.at("roots").at(i).at(key))throw std::runtime_error("commit root baseline changed");
 std::array<Artifact,3> files;const std::array<const char*,3> roles={"original","backup","temporary"};
 for(size_t i=0;i<3;i++){auto p=paths.at(i);if(!keys(p,{"role","path"})||p.at("role")!=roles[i])throw std::runtime_error("commit role order");files[i].role=roles[i];files[i].name=normal(wide(p.at("path").get<std::string>()));leafOf(files[i].name);if(!inside(i==1?backupRoot:sourceRoot,files[i].name))throw std::runtime_error("commit file escaped frozen root");}
 const auto parent=parentOf(files[0].name);const auto job=r.at("jobId").get<std::string>();const auto victim=parent+(parent.back()==L'\\'?L"":L"\\")+L".aural-"+wide(job)+L"-"+wide(r.at("victimArtifactId").get<std::string>())+L".victim";
 const auto tempLeaf=leafOf(files[2].name),backupLeaf=leafOf(files[1].name),tempPrefix=L".aural-"+wide(job)+L"-",backupPrefix=wide(job)+L"-";
 if(parentOf(files[2].name)!=parent||parentOf(files[1].name)!=backupRoot||tempLeaf.size()!=tempPrefix.size()+40||tempLeaf.substr(0,tempPrefix.size())!=tempPrefix||tempLeaf.substr(tempLeaf.size()-4)!=L".tmp"||backupLeaf.size()!=backupPrefix.size()+40||backupLeaf.substr(0,backupPrefix.size())!=backupPrefix||backupLeaf.substr(backupLeaf.size()-4)!=L".bak"||files[0].name==files[2].name||files[0].name==files[1].name||files[0].name.size()<5||files[0].name.substr(files[0].name.size()-5)!=L".flac")throw std::runtime_error("commit artifact names differ from frozen layout");
 HANDLE parentHandle=pins.pin(parent,true);for(size_t i=0;i<3;i++)openArtifact(files[i],i!=1);
 for(size_t i=0;i<3;i++){hashArtifact(files[i]);if(files[i].result!=expected.at("files").at(i))throw std::runtime_error("commit full file evidence differs from inspection");}
 if(files[0].result.at("flac")!=files[1].result.at("flac")||files[0].result.at("flac").at("audioSha256")!=files[2].result.at("flac").at("audioSha256")||files[0].result.at("flac").at("audioBytes")!=files[2].result.at("flac").at("audioBytes")||files[0].result.at("sha256")==files[2].result.at("sha256"))throw std::runtime_error("commit backup/audio/target evidence invalid");
 auto proof=[&](const json& policy){return json{{"files",{files[0].result,files[1].result,files[2].result}},{"roots",roots},{"parent",identity(parentHandle,true)},{"policy",policy},{"leaseId",r.at("leaseId")},{"leaseRevision",r.at("leaseRevision")},{"certificateId",r.at("certificateId")},{"victimArtifactId",r.at("victimArtifactId")}};};
 receipt("locked",proof(nullptr));json policy=preparePolicy(files[0],files[2]);hashArtifact(files[0]);if(files[0].result!=expected.at("files").at(0))throw std::runtime_error("source changed while preparing attribute policy");hashArtifact(files[2]);receipt("intent",proof(policy));
 auto stable=[&]{if(finalPath(source)!=sourceRoot||finalPath(backup)!=backupRoot||finalPath(parentHandle)!=parent)throw std::runtime_error("commit directory path changed");for(auto& file:files)if(identity(file.handle.value,false)!=file.result.at("identity")||finalPath(file.handle.value)!=file.name)throw std::runtime_error("file identity changed before move");OriginPolicyBytes archive(policy.at("origin"));archive.verify(files[0].handle.value);FILE_BASIC_INFO basic{};if(!GetFileInformationByHandleEx(files[0].handle.value,FileBasicInfo,&basic,sizeof(basic))||std::to_string(ticks(basic.CreationTime))!=policy.at("origin").at("creation")||std::to_string(ticks(basic.LastWriteTime))!=policy.at("origin").at("modified")||basic.FileAttributes!=policy.at("origin").at("attributes"))throw std::runtime_error("original archived basic policy changed");Security s(files[0].handle.value),t(files[2].handle.value);if(securityEvidence(s)!=policy.at("security")||securityEvidence(t)!=policy.at("security"))throw std::runtime_error("permission policy changed before move");};stable();
 // There is an explicit recoverable gap between the two non-overwriting moves.
 // No rollback, overwrite, delete or automatic retry can hide an uncertain move.
 renameAbsent(files[0],parentHandle,victim);files[0].role="victim";hashArtifact(files[0]);receipt("victim_moved",proof(policy));stable();
 renameAbsent(files[2],parentHandle,normal(wide(paths.at(0).at("path").get<std::string>())));files[2].role="destination";hashArtifact(files[2]);receipt("replaced",proof(policy));
 hashArtifact(files[0]);hashArtifact(files[2]);stable();if(files[0].result.at("flac")!=expected.at("files").at(0).at("flac")||files[2].result.at("flac")!=expected.at("files").at(2).at("flac"))throw std::runtime_error("commit final reread differs");receipt("verified",proof(policy));stable();send({{"kind","done"},{"proof",proof(policy)}});
}
int wmain(int argc,wchar_t** argv){return runTagNativeTransaction(argc,argv,commit);}
